--- /app/public/styles.css
+++ /app/public/styles.css
@@ -1 +1,2 @@
-
+@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap');
+:root{--ink:#161b18;--muted:#667069;--paper:#f5f4ef;--card:#fff;--line:#d9ddd8;--green:#123e2d;--lime:#c8f25d;--rust:#bd5b39}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif}button,input,select,textarea{font:inherit}button,a{cursor:pointer}header{min-height:78px;padding:0 5vw;display:flex;align-items:center;gap:34px;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:10}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink)}.brand img{width:42px}.brand span{display:flex;flex-direction:column}.brand b{font:800 17px Manrope;letter-spacing:.13em}.brand small{color:var(--muted);font-size:11px}nav{display:flex;gap:22px;margin-left:auto}nav a{color:var(--muted);text-decoration:none;font-weight:600;font-size:14px}.switcher{display:flex;flex-direction:column;font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.switcher select{border:0;background:transparent;font-weight:700;color:var(--ink);max-width:185px}.hero{min-height:440px;background:var(--green);color:white;padding:72px 8vw;display:flex;align-items:center;justify-content:space-between;gap:50px;overflow:hidden;position:relative}.hero:after{content:'';position:absolute;width:360px;height:360px;border:80px solid rgba(200,242,93,.08);border-radius:50%;right:-80px;top:-100px}.hero>div:first-child{max-width:720px;z-index:1}.eyebrow{color:var(--lime);letter-spacing:.18em;font-size:12px;font-weight:700}.hero h1{font:700 clamp(42px,6vw,76px)/1.02 Manrope;margin:18px 0}.hero h1 em{color:var(--lime);font-style:normal}.hero p:not(.eyebrow){max-width:600px;color:#c8d4cd;font-size:18px}.hero-stat{background:#fff;color:var(--ink);padding:28px;width:230px;z-index:1;box-shadow:12px 12px 0 var(--lime)}.hero-stat>span{font-size:11px;letter-spacing:.14em;color:var(--muted)}.hero-stat strong{font:800 72px Manrope;display:block}.hero-stat small{color:var(--muted)}.hero-stat div{border-top:1px solid var(--line);margin-top:18px;padding-top:15px;font-size:12px}.hero-stat i{display:inline-block;width:8px;height:8px;border-radius:50%;background:#37a66a;margin-right:5px}main>section:not(.hero),#notice{max-width:1200px;margin:auto}.section{padding:64px 24px}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:28px}.section-head h2{font:800 34px Manrope;margin:0}.section-head p{color:var(--muted);margin:7px 0 0}.filters{display:flex;gap:8px;flex-wrap:wrap}.filters button,.chip{border:1px solid var(--line);background:#fff;border-radius:20px;padding:8px 13px}.filters button.active{background:var(--ink);color:#fff}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:var(--card);border:1px solid var(--line);padding:22px;position:relative}.card:hover{border-color:#9da69f}.tag{font:700 12px Manrope;letter-spacing:.1em;color:var(--rust)}.card h3{font:700 20px Manrope;margin:10px 0 4px}.muted{color:var(--muted)}.meta{display:flex;gap:15px;margin:20px 0;font-size:13px}.price{font:800 24px Manrope}.price small{font:400 12px DM Sans;color:var(--muted)}.status{display:inline-flex;align-items:center;gap:6px;font-size:11px;text-transform:uppercase;letter-spacing:.08em}.status:before{content:'';width:7px;height:7px;border-radius:50%;background:#36a36a}.status.bad:before{background:var(--rust)}.btn{display:inline-block;border:0;background:var(--lime);color:#172016;padding:12px 18px;font-weight:700;text-decoration:none}.btn.dark{background:var(--green);color:#fff}.btn.ghost{background:#fff;border:1px solid var(--line)}.btn.danger{background:#f7dfd8;color:#8a321d}.card .btn{width:100%;margin-top:12px}.panel{background:#fff;border:1px solid var(--line);padding:24px;margin-bottom:16px}.panel h3{font:700 20px Manrope;margin-top:0}.row{display:flex;gap:14px;align-items:center;flex-wrap:wrap}.row.between{justify-content:space-between}.stack{display:grid;gap:13px}.field{display:grid;gap:6px;flex:1;min-width:150px}.field label{font-size:12px;font-weight:700}.field input,.field select,.field textarea{width:100%;padding:11px;border:1px solid var(--line);background:#fff}.total{font:800 32px Manrope}.breakdown{border-top:1px solid var(--line);margin-top:15px;padding-top:10px}.breakdown div{display:flex;justify-content:space-between;padding:5px 0}.record{display:grid;grid-template-columns:1fr auto;gap:18px;padding:17px 0;border-bottom:1px solid var(--line)}.record:last-child{border:0}.record h4{margin:0 0 4px}.empty{text-align:center;padding:45px;color:var(--muted)}#notice{position:fixed;right:24px;top:92px;z-index:30;width:min(390px,calc(100vw - 48px));margin:0}#notice>div{padding:15px 18px;background:var(--ink);color:white;box-shadow:0 8px 30px #0003;border-left:5px solid var(--lime)}#notice .error{border-color:var(--rust)}dialog{width:min(620px,94vw);border:0;padding:30px;box-shadow:0 20px 80px #0006}dialog::backdrop{background:#0d1d16aa}.close{float:right;border:0;background:none;font-size:28px}footer{padding:30px 5vw;background:#101713;color:#a9b4ad;display:flex;gap:18px;align-items:center;font-size:12px}footer img{width:28px}footer span:last-child{margin-left:auto}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{text-align:left;padding:11px;border-bottom:1px solid var(--line)}.role-banner{background:#e7ecdf;padding:16px 24px;border-left:5px solid var(--green);margin-bottom:20px}.two-col{display:grid;grid-template-columns:1.3fr .7fr;gap:18px}@media(max-width:850px){header{padding:12px 18px;flex-wrap:wrap}.brand{margin-right:auto}nav{order:3;width:100%;overflow:auto;margin:0}.hero{padding:55px 24px}.hero-stat{display:none}.grid{grid-template-columns:repeat(2,1fr)}.two-col{grid-template-columns:1fr}}@media(max-width:560px){.grid{grid-template-columns:1fr}.section{padding:44px 16px}.hero h1{font-size:42px}.switcher{width:150px}.record{grid-template-columns:1fr}.table{display:block;overflow:auto}footer{flex-wrap:wrap}footer span:last-child{margin:0}}
